package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="app_users") public class AppUser{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=255) private String email; @Column(name="display_name",nullable=false,length=150) private String displayName; @Column(nullable=false,length=40) private String role; @Column(nullable=false,length=20) private String status="ACTIVE"; @Column(name="mfa_required",nullable=false) private boolean mfaRequired=true; @ElementCollection @CollectionTable(name="user_customer_scopes",joinColumns=@JoinColumn(name="user_id")) @Column(name="customer_id") private Set<UUID> customerIds=new HashSet<>(); @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 @PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=Instant.now();}
 public UUID getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getDisplayName(){return displayName;} public void setDisplayName(String v){displayName=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public boolean isMfaRequired(){return mfaRequired;} public void setMfaRequired(boolean v){mfaRequired=v;} public Set<UUID> getCustomerIds(){return customerIds;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}
